    answer: "電磁波の危険性は科学的にまだ証明されていないが、気になるなら電子レンジを使わないのも選択肢。勝間さん自身は湯煎や蒸しで温め直しをしている。もし電磁波が本当に危険なら先進国でもっと多くの健康被害が出ているはず。過度な恐怖より実用性とのバランスで判断を。"
