    name: "Mさん", tag: "健康・医療",
    question: "更年期障害について知りたい。治療されたならどのような観点で選択したのか、生活で意識していることを教えてほしい。",
    answer: "ホルモン補充療法は天然型を使えばがんリスクは上がらないという最新の知見。辛かったら補充療法、辛くなければ運動を続けることが基本。信頼できる医師を友人の口コミで探すのが最善。"
