    videoId: "4aV7fxH4A9g", qNum: 3, timestamp: "14:02", seconds: 842,
    name: "やのちゃんさん", tag: "キャリア",
    question: "職場で退職者が増え人手不足が深刻。自分も退職したいが引き継ぎを考えて半年以上前に退職届を出すつもりでいる。勝間さんの考え方を教えてほしい。",
    answer: "半年待つ必要はない。会社の構造が悪いのであって個人が引き継ぎのために留まり続ける義務はない。法律上は2週間前に届け出れば退職できる。会社が問題を起こしているのだから早めに退職してよい。",
