    videoId: "4aV7fxH4A9g", qNum: 8, timestamp: "51:56", seconds: 3116,
    name: "マリンさん", tag: "コミュニケーション",
    question: "内向的な性格で積極的に人付き合いができない。内向的な人間が積極的な気になれるコツや心構えを教えてほしい。",
    answer: "内向的か外向的かを決めつける必要はない。まず少人数（1〜2人）と深い関係を築くことから始め、オンラインのコミュニティを活用するのも有効。人付き合いの量より質を高めることを目指すと気が楽になる。"
