    name: "デンジャラスカーさん", tag: "趣味",
    question: "田舎に住んでおり車の運転が必要だが苦手でヒヤッとすることが多い。安全運転できる方法を教えてほしい。",
    answer: "答えは1つ、安全性能が高い車（360度カメラ・センサー搭載）にしか乗らないこと。自分の技術を上げるより車の安全装備に頼る方が現実的で効果的。レンタカーも360度監視ができる車種から選ぶ。"
