    answer: "FitbitなどのウェアラブルデバイスでのトレーニングとSleepの差は正常範囲。睡眠の質を上げるためには就寝前のルーティン（スマホを見ない・照明を落とす）を徹底し、実際の睡眠時間が7時間確保できるよう布団に入る時間を早めることが重要。"
