    name: "ルビーさん", tag: "副業",
    question: "65歳でジムパートを終了し時間が生まれる。文章執筆とSNSのフォロワー約1000人だが収益化未達。最適な行動順序を教えてほしい。",
    answer: "順番はどうでもよい。良いコンテンツが売れるかどうかは市場が決める。発信を続けることが先決でニッチでも質のいい内容は口コミで自然に広がる。収益化手段の選択より、まず読者の役に立つ内容を積み重ねることが重要。"
