    name: "カモミールさん", tag: "コミュニケーション",
    question: "還暦過ぎの海外在住者。幼少期から兄の嫉妬・いじめ・遺産独占に苦しんできた。将来独身で金銭にルーズな兄が問題になる前に絶縁したい。",
