    name: "嫁さん", tag: "子育て・教育",
    question: "1歳4ヶ月と2ヶ月の子2人を育てている。周囲の「私はそんなに大変じゃなかった」などの言葉にモヤモヤする。うまく飲み込む方法や周りとうまくやる方法を教えてほしい。",
    answer: "育児経験者が「大変じゃなかった」と言うのは実情の違いや記憶の美化が原因。義両親や夫の期待を全て満たそうとしなくてよい。自分の現状を正当に評価し、無理のない範囲で対応することが大切。"
