    name: "サリーさん", tag: "キャリア",
    question: "夫の研究留学に同道し半年前にアメリカに転居。限られた滞在期間中に収入・キャリア継続・英語学習・人脈作りのバランスをどうとればよいか。",
    answer: "英語力向上と現地人脈づくりは帰国後にできないので在米期間に最優先。キャリアは帰国後も積める部分があるため、この機会にしかできない英語と人脈に集中することを勧める。"
