    name: "うさ子さん", tag: "健康・医療",
    question: "在ドイツ25年以上。将来日本との2拠点生活を夢見ているが、長距離フライトの環境への影響に後ろめたさを感じる。この気持ちとどう向き合えばよいか。",
    answer: "飛行機の問題は環境より自分の体への影響（低気圧・放射線被曝）の方が実質的に大きい。環境への罪悪感より自分の健康管理（フライト後の休養・水分補給等）を優先することを勧める。"
